import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.dirname(path.dirname(fileURLToPath(import.meta.url)));
const legal = JSON.parse(fs.readFileSync(path.join(root, 'src/data/legal.json'), 'utf8'));
const out = path.join(root, 'public/api/_mail_config.php');

const to = legal.email || 'sale@gipergidroz.su';
const site = legal.site_host || 'gipergidroz.su';

const php = `<?php
// generated by scripts/generate-mail-config.mjs — do not edit
return [
    'to' => '${to}',
    'from' => 'noreply@${site}',
    'site' => '${site}',
];
`;

fs.writeFileSync(out, php);
console.log('Generated', out, '→', to);
